import{c as a,Q as i,j as r,m as t}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Recursively Trained Diffusion Models: Limiting Collapse Distribution and Spectral Characterization","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.13796","title":"Recursively Trained Diffusion Models: Limiting Collapse Distribution and Spectral Characterization","archived_date":"2026-07-31T00:00:00.000Z","arxiv_id":2606.13796,"authors":["Naïl B. Khelifa","Richard E. Turner","Ramji Venkataramanan"],"domain":"model-collapse-recursive-training","published_date":"2026-06-11T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-31-model-collapse-diffusion-spectral-2606-13796.md","filePath":"research/papers/2026-07-31-model-collapse-diffusion-spectral-2606-13796.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-07-31-model-collapse-diffusion-spectral-2606-13796.md"};function s(n,e,l,c,d,p){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="recursively-trained-diffusion-models-limiting-collapse-distribution-and-spectral-characterization" tabindex="-1">Recursively Trained Diffusion Models: Limiting Collapse Distribution and Spectral Characterization <a class="header-anchor" href="#recursively-trained-diffusion-models-limiting-collapse-distribution-and-spectral-characterization" aria-label="Permalink to &quot;Recursively Trained Diffusion Models: Limiting Collapse Distribution and Spectral Characterization&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文研究 diffusion model 遞迴訓練在自身輸出上導致的 model collapse，找出一個先前被忽略的機制：即使 score 估計完美、取樣精確，反向擴散過程為數值穩定所做的「提前停止（early stopping）」本身就足以驅動一種漸進式、系統性偏離真實資料分佈的 drift——也就是說，即使每一步技術上都做對，崩潰仍會發生。</p><p>主要貢獻是證明遞迴訓練會以幾何速度收斂到一個獨特的極限分佈，該分佈可表示為真實資料分佈之高斯平滑化版本的無窮混合。頻譜分析進一步顯示，遞迴訓練的作用等同於一個低通濾波器：對高階非高斯特徵的壓制遠比對粗糙特徵劇烈——換言之，分佈的細部結構是崩潰的第一個受害者，而非整體平均品質。論文提出退火截斷排程（annealed truncation schedules）來緩解誤差累積，並在 Gaussian mixture 與 CIFAR-10 上驗證，理論框架在存在離散化誤差與 score 估計誤差時依然穩健。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>本文刻畫的是遞迴訓練導致崩潰的<strong>解析機制</strong>（極限分佈存在性、幾何收斂速度、頻譜低通特徵），這在 workspace 既有覆蓋（agent harness、memory/context engineering、machine-unlearning）中完全未觸及。既有唯一提及 model collapse 的既存論文（<code>2607-07663</code> 遞迴自我改進分類法）僅將其列為失效模式分類項之一，未涉及任何機制層內容；<code>spectral characterization</code>／<code>autophagy</code>／<code>self-consuming</code> 等本文核心術語在全庫（reports/papers/DAILY-TOPICS/WEEKLY-FOCUS）0 命中。</p>',6)])])}const f=a(o,[["render",s]]);export{h as __pageData,f as default};
